// Test-only: the small .xlsx files of src/test/xlsx/ (generated by web/scripts/gen_test_xlsx.py) and a DOMParser for the node test environment
// (the real code uses the browser's; @xmldom/xmldom is a devDependency used by tests only).
import { DOMParser } from "@xmldom/xmldom";
import { zipSync, strToU8 } from "fflate";

(globalThis as unknown as { DOMParser: unknown }).DOMParser = DOMParser;

// no @types/node in this project: read the files with node:fs through file URLs
// @ts-ignore node:fs has no type declarations unless @types/node is installed (it arrives transitively with firebase)
const fs = (await import("node:fs")) as { readFileSync(u: URL): Uint8Array; existsSync(u: URL): boolean };

export const xlsxBytes = (name: string): Uint8Array => new Uint8Array(fs.readFileSync(new URL(`./xlsx/${name}`, import.meta.url)));
export const xlsxJson = <T>(name: string): T => JSON.parse(new TextDecoder().decode(fs.readFileSync(new URL(`./xlsx/${name}`, import.meta.url)))) as T;

/** A zip made in memory (for the error cases: not a workbook, macro-enabled, ...). */
export const makeZip = (files: Record<string, string>): Uint8Array => zipSync(Object.fromEntries(Object.entries(files).map(([k, v]) => [k, strToU8(v)])));
